-- Review-gated BIS certification, hallmarking and Electronics/IT registration routes.

do $$
declare
  item jsonb;
  authority_id uuid;
  seed_opportunity_id uuid;
  version_id uuid;
begin
  for item in
    select value from jsonb_array_elements($records$[
      {"slug":"bis-fmcs-foreign-manufacturer-licence","name":"BIS Foreign Manufacturers Certification Scheme (FMCS)","type":"product_certification","status":"active","authority":"Bureau of Indian Standards - Foreign Manufacturers Certification Scheme","authority_url":"https://www.bis.gov.in/","canonical_url":"https://www.bis.gov.in/fmcs/fmcs-overview/?lang=en","source_url":"https://www.bis.gov.in/fmcs/fmcs-overview/?lang=en","source_kind":"agency_portal","source_title":"BIS FMCS overview","source_anchor":"Foreign manufacturer licensing, Indian Standard conformity, Authorized Indian Representative and Electronics/IT boundary","summary":"Certification route for foreign manufacturers seeking a BIS licence to use the Standard Mark for products conforming to applicable Indian Standards.","objective":"Guide a foreign factory through product/standard classification, testing, Indian representation, application and post-licence obligations.","legal_basis":"BIS Act and applicable Indian Standards, Quality Control Orders and BIS FMCS procedures; current product notification controls whether certification is voluntary or compulsory.","eligibility":{"entity_types":["foreign_manufacturer","foreign_factory"],"lifecycle_stages":["starting","operating","exporting_to_india"],"industries":["manufacturing","consumer_goods","industrial_equipment","chemicals","mechanical","electrical","construction_products"],"locations":["outside_india","india_market"],"conditions":["foreign factory must manufacture the product and conform to the applicable Indian Standard","factory must have required manufacturing, testing and quality-control capability","an Authorized Indian Representative is required for the application and licence relationship","a separate application is required for each product/Indian Standard and factory combination","Electronics and IT products notified by MeitY follow the separate CRS route","current QCO or product notification determines whether BIS certification is compulsory"],"thresholds":{"separate_application_per_product_standard_factory":true,"authorized_indian_representative_required":true,"meity_electronics_it_boundary":"separate CRS route","online_application_only_from":"2026-06-01"},"unknown_handling":"needs_information"},"application":{"portal":"https://www.manakonline.in/","route":"Confirm the Indian Standard and notification, prepare product and factory evidence, nominate an Authorized Indian Representative, complete testing and submit the online FMCS application with applicable fees.","selection":"BIS evaluates the factory, test results, documents and conformity; UdyamVeda cannot issue a BIS licence.","fees":"Applicable application, inspection, testing and licence fees must be confirmed from the current BIS schedule.","applicant_note":"UdyamVeda may prepare an evidence checklist and explain the route but must not act as BIS or impersonate the foreign applicant or representative."},"fine_print":{"scope":"FMCS is for foreign manufacturers seeking a BIS licence and Standard Mark for products conforming to Indian Standards.","product_boundary":"Products notified by MeitY under Electronics and IT use CRS rather than FMCS; QCOs can make certification compulsory for specified products.","process_boundary":"The current BIS application page indicates online submission and an online-only route from June 1, 2026; confirm the live portal and applicable transition rules before publication.","review_note":"Verify the applicable Indian Standard, QCO, product scope, factory testing capability, Authorized Indian Representative, fees, inspection, validity, marking and surveillance conditions before publication."},"benefit_summary":{"types":["regulatory_approval","market_access"],"summary":"BIS product certification and Standard Mark route for eligible foreign manufacturers; not a grant, subsidy or loan.","separate_value_buckets":true},"benefit_type":"regulatory_approval","benefit_label":"BIS FMCS licence and Standard Mark route","amount_min":null,"amount_max":null,"percentage":null,"benefit_conditions":{"product_standard_conformity_required":true,"authorized_indian_representative_required":true,"product_notification_must_be_checked":true,"crs_boundary_for_meity_electronics_it":true},"requirement":"Product/Indian Standard classification, factory capability, test evidence, Authorized Indian Representative and applicant records","requirement_description":"Prepare manufacturer identity, factory address, product specification, applicable Indian Standard, in-house testing facility/personnel, test reports, quality records, representative authorization and current BIS forms.","rules":{"all":[{"field":"foreign_factory_verified","operator":"equals","value":true},{"field":"applicable_indian_standard_verified","operator":"equals","value":true},{"field":"authorized_indian_representative_confirmed","operator":"equals","value":true},{"field":"required_factory_testing_capability_verified","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Classify product and notification","description":"Identify the Indian Standard, QCO status and whether FMCS or CRS applies.","url":"https://www.bis.gov.in/fmcs/fmcs-faqs/?lang=en"},{"title":"Confirm factory and representative readiness","description":"Confirm factory capability, testing resources and the Authorized Indian Representative.","url":"https://www.bis.gov.in/fmcs/certification-process/who-can-apply/?lang=en"},{"title":"Prepare testing and application evidence","description":"Assemble product, factory, test, quality and applicant records.","url":"https://www.bis.gov.in/fmcs/certification-process/how-to-apply/?lang=en"},{"title":"Submit and complete BIS evaluation","description":"Submit through the official portal, respond to inspection or testing requests and track the decision.","url":"https://www.manakonline.in/"}],"window_type":"rolling","window_close_at":null,"window_label":"Rolling certification route; current portal, notification, testing and licence conditions determine timing.","window_evidence":{"source_url":"https://www.bis.gov.in/fmcs/certification-process/how-to-apply/?lang=en","anchor":"BIS application process, Authorized Indian Representative, online submission and applicable fees."},"review_note":"Keep review-gated. This record describes a certification route, not a guaranteed licence or financial benefit."},
      {"slug":"bis-hallmarking-jeweller-registration","name":"BIS Registration of Jewellers for Sale of Hallmarked Gold and Silver Articles","type":"compliance_registration","status":"active","authority":"Bureau of Indian Standards - Hallmarking","authority_url":"https://www.bis.gov.in/","canonical_url":"https://www.bis.gov.in/hallmarking-jewellers/?lang=en","source_url":"https://www.bis.gov.in/hallmarking-jewellers/?lang=en","source_kind":"agency_portal","source_title":"BIS hallmarking jewellers","source_anchor":"Jeweller registration, gold and silver scope, turnover exemption and online application route","summary":"BIS registration route for jewellers selling hallmarked gold or silver articles, with current hallmarking obligations and exemptions made explicit.","objective":"Help jewellery businesses determine registration, hallmarking and record obligations before selling covered articles.","legal_basis":"BIS hallmarking framework and current BIS jeweller registration guidance; mandatory hallmarking notifications and turnover limits control the case.","eligibility":{"entity_types":["jeweller","manufacturer","wholesaler","distributor","retailer","gold_silver_article_seller"],"lifecycle_stages":["starting","operating","expanding"],"industries":["jewellery","precious_metals","retail","manufacturing","wholesale"],"locations":["India","hallmarking_mandatory_district"],"conditions":["business sells or proposes to sell hallmarked gold or silver articles","registration route and hallmarking category must be checked for the business and articles","only gold and silver are currently within the BIS hallmarking scope described in the official overview","businesses below the current mandatory-hallmarking turnover threshold may have an exemption from mandatory hallmarking but can still register","job workers and other excluded cases require supporting evidence and current guidance"],"thresholds":{"current_turnover_exemption_reference_inr":4000000,"registration_fee":0,"registration_validity":"lifetime","registration_processing":"instant_subject_to_portal_acceptance"},"unknown_handling":"needs_information"},"application":{"portal":"https://www.manakonline.in/","alternate_portal":"https://www.nsws.gov.in/","route":"Confirm the article, business and mandatory-hallmarking category, submit the jeweller registration through the official route and retain registration details.","selection":"BIS controls registration and hallmarking compliance; UdyamVeda cannot register the jeweller or certify an article.","fees":"The BIS overview states no registration fee; confirm the live portal and any separate hallmarking, assay or testing charges.","applicant_note":"UdyamVeda may prepare the business and article checklist but must not represent itself as BIS or submit on the applicant's behalf without explicit authorized assistance."},"fine_print":{"scope":"BIS states that jeweller registration supports sale of hallmarked gold and silver articles; manufacturer, wholesaler, distributor and retailer roles may be covered.","exemption":"The official jeweller page describes an exemption from mandatory hallmarking for turnover up to INR 40 lakh; confirm the current notification and whether the exemption applies to the specific articles and location.","registration":"The BIS hallmarking overview describes instant registration, no registration fee and lifetime validity; portal and category checks remain necessary.","review_note":"Verify current mandatory districts, article exemptions, turnover treatment, registration fields, hallmarking centre/assaying charges, records, renewal and enforcement before publication."},"benefit_summary":{"types":["regulatory_approval","compliance"],"summary":"BIS jeweller registration and hallmarking compliance route; not a grant, subsidy or loan.","separate_value_buckets":true},"benefit_type":"compliance_registration","benefit_label":"BIS jeweller registration for hallmarked gold and silver articles","amount_min":null,"amount_max":null,"percentage":null,"benefit_conditions":{"gold_and_silver_scope_check_required":true,"mandatory_hallmarking_notification_check_required":true,"turnover_exemption_may_apply":true,"registration_fee_reference_inr":0,"registration_validity":"lifetime"},"requirement":"Jeweller identity, business address, article category, turnover and current registration declarations","requirement_description":"Prepare entity and premises details, authorized-person information, business activity, article category, turnover evidence where relevant and current portal declarations.","rules":{"all":[{"field":"jeweller_identity_verified","operator":"equals","value":true},{"field":"articles_and_hallmarking_scope_verified","operator":"equals","value":true},{"field":"current_bis_registration_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Classify articles and business role","description":"Confirm gold/silver scope, business role, mandatory district and current exemption conditions.","url":"https://www.bis.gov.in/hallmarking-overview/?lang=en"},{"title":"Prepare registration evidence","description":"Assemble business, premises, authorized-person and turnover information.","url":"https://www.bis.gov.in/wp-content/uploads/2024/01/Revised-Guidelines-for-JEWELLERS-Jan-24.pdf"},{"title":"Submit jeweller registration","description":"Use the official BIS or NSWS route and retain the registration record.","url":"https://www.bis.gov.in/apply-for-jewellers-registration/?lang=en"},{"title":"Maintain hallmarking records","description":"Track article, hallmarking, assaying and record obligations under current BIS rules.","url":"https://www.bis.gov.in/hallmarking-jewellers/?lang=en"}],"window_type":"rolling","window_close_at":null,"window_label":"Standing registration route; current hallmarking notifications, district coverage and article conditions determine obligations.","window_evidence":{"source_url":"https://www.bis.gov.in/hallmarking-jewellers/?lang=en","anchor":"Official jeweller registration, turnover-exemption and application information."},"review_note":"Keep review-gated. This record is a compliance route and must not imply that registration itself hallmarks or approves articles."},
      {"slug":"bis-crs-electronics-it-registration","name":"BIS Compulsory Registration Scheme (CRS) for Electronics and IT Products","type":"product_certification","status":"active","authority":"Bureau of Indian Standards - Compulsory Registration Scheme","authority_url":"https://www.bis.gov.in/","canonical_url":"https://www.crsbis.in/BIS/about-crs.do","source_url":"https://www.crsbis.in/BIS/about-crs.do","source_kind":"agency_portal","source_title":"BIS Compulsory Registration Scheme portal","source_anchor":"Electronics and IT product registration route and Standard Mark boundary","summary":"Registration route for notified Electronics and IT products that must meet the applicable Indian Standard and use the BIS Standard Mark under CRS.","objective":"Help electronics and IT manufacturers determine product-notification coverage, test evidence, registration and ongoing marking obligations.","legal_basis":"BIS product-registration framework and MeitY Electronics and IT product notifications; the current notified product list and standard control the case.","eligibility":{"entity_types":["electronics_manufacturer","it_product_manufacturer","foreign_manufacturer","importer_supported_manufacturer"],"lifecycle_stages":["starting","operating","exporting_to_india"],"industries":["electronics","information_technology","consumer_electronics","electrical_equipment","telecommunications"],"locations":["India","outside_india","india_market"],"conditions":["product must be within the current MeitY-notified Electronics and IT product list","product must conform to the applicable Indian Standard","recognized laboratory test evidence and manufacturer records are required","registration is product and manufacturer specific and the current portal controls forms and fees","CRS is the relevant route for notified Electronics and IT products rather than FMCS"],"thresholds":{"meity_notification_required":true,"applicable_indian_standard_required":true,"separate_product_manufacturer_registration":"current portal and notification control","foreign_manufacturer_route":"current CRS guidance and representative requirements must be confirmed"},"unknown_handling":"needs_information"},"application":{"portal":"https://www.crsbis.in/BIS/about-crs.do","route":"Check the notified product list and Indian Standard, arrange testing through the recognized route, prepare manufacturer and product evidence, and submit the current CRS registration.","selection":"BIS and the notified product regime control registration; UdyamVeda cannot issue CRS registration or certify a product.","fees":"Current testing, application, registration and renewal/validity conditions must be confirmed from the live CRS portal.","applicant_note":"UdyamVeda may explain the route and document checklist but must not represent itself as BIS or guarantee registration."},"fine_print":{"scope":"BIS distinguishes CRS for notified Electronics and IT products from FMCS; product notification and current standard determine applicability.","testing":"A current recognized-laboratory test route and product/manufacturer evidence must be confirmed for the specific product and application.","market_access":"Registration is a regulatory market-access prerequisite for covered products; it is not a grant or approval of every product variation.","review_note":"Verify the current MeitY product list, Indian Standard, laboratory route, applicant/representative requirements, fees, validity, marking, modifications, surveillance and renewal before publication."},"benefit_summary":{"types":["regulatory_approval","market_access"],"summary":"BIS CRS product registration and Standard Mark route for notified Electronics and IT products; not a financial benefit.","separate_value_buckets":true},"benefit_type":"regulatory_approval","benefit_label":"BIS CRS registration and Standard Mark route","amount_min":null,"amount_max":null,"percentage":null,"benefit_conditions":{"meity_notification_check_required":true,"indian_standard_conformity_required":true,"recognized_lab_evidence_required":true,"fmcs_boundary_must_be_checked":true},"requirement":"Notified product classification, Indian Standard, test report, manufacturer identity and current CRS declarations","requirement_description":"Prepare product model/specification, applicable notification and Indian Standard, recognized-lab test report, manufacturer address, authorized-person details and current portal documents.","rules":{"all":[{"field":"electronics_or_it_product_verified","operator":"equals","value":true},{"field":"current_meity_notification_verified","operator":"equals","value":true},{"field":"applicable_indian_standard_verified","operator":"equals","value":true},{"field":"recognized_lab_evidence_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Check notified product scope","description":"Confirm the product is currently covered by the MeitY Electronics and IT notification.","url":"https://www.bis.gov.in/fmcs/fmcs-overview/?lang=en"},{"title":"Map the Indian Standard and test route","description":"Confirm the applicable standard and recognized laboratory evidence for the model.","url":"https://www.crsbis.in/BIS/about-crs.do"},{"title":"Prepare manufacturer and product records","description":"Assemble product, model, manufacturer, test and authorized-person information.","url":"https://www.crsbis.in/BIS/about-crs.do"},{"title":"Submit CRS registration","description":"Use the official CRS portal, respond to queries and retain the registration record.","url":"https://www.crsbis.in/BIS/about-crs.do"}],"window_type":"rolling","window_close_at":null,"window_label":"Standing product-registration route; notified product list, standards and portal requirements determine timing.","window_evidence":{"source_url":"https://www.bis.gov.in/fmcs/fmcs-overview/?lang=en","anchor":"BIS overview identifies CRS as the separate route for Electronics and IT products notified by MeitY."},"review_note":"Keep review-gated. Do not publish a product-level eligibility decision without checking the current notification and standard."}
    ]$records$::jsonb)
  loop
    authority_id := null;
    select id into authority_id from public.authorities where name = item->>'authority' and level = 'central' order by created_at, id limit 1;
    if authority_id is null then
      insert into public.authorities (name, level, ministry, department, official_url)
    values (item->>'authority', 'central', 'Ministry of Consumer Affairs, Food and Public Distribution', 'Bureau of Indian Standards', item->>'authority_url')
    returning id into authority_id;
    end if;
    if authority_id is null then select id into authority_id from public.authorities where name = item->>'authority' limit 1; end if;
    seed_opportunity_id := null;
    insert into public.opportunities (slug, name, opportunity_type, status, authority_id, geography, canonical_url)
    values (item->>'slug', item->>'name', item->>'type', item->>'status', authority_id, '{"coverage":"central","locations":["India"]}'::jsonb, item->>'canonical_url')
    on conflict (slug) do update set name = excluded.name, status = excluded.status, authority_id = excluded.authority_id, canonical_url = excluded.canonical_url
    returning id into seed_opportunity_id;
    if seed_opportunity_id is null then select id into seed_opportunity_id from public.opportunities where slug = item->>'slug' limit 1; end if;
    version_id := null;
    insert into public.opportunity_versions
      (opportunity_id, version_number, title, summary, objective, legal_basis, eligibility, application, fine_print, benefit_summary, last_verified_at, completeness, confidence, review_status)
    values (seed_opportunity_id, 1, item->>'name', item->>'summary', item->>'objective', item->>'legal_basis', item->'eligibility', item->'application', item->'fine_print', item->'benefit_summary', now(), 0.9, 0.85, 'in_review')
    on conflict (opportunity_id, version_number) do nothing
    returning id into version_id;
    if version_id is null then select ov.id into version_id from public.opportunity_versions ov where ov.opportunity_id = seed_opportunity_id and ov.version_number = 1 limit 1; end if;
    update public.opportunities set current_version_id = version_id, status = item->>'status' where id = seed_opportunity_id;
    insert into public.opportunity_sources (opportunity_version_id, source_url, source_kind, source_title, source_anchor, fetched_at, is_primary)
    values
      (version_id, item->>'source_url', item->>'source_kind', item->>'source_title', item->>'source_anchor', now(), true),
      (version_id, 'https://www.bis.gov.in/fmcs/fmcs-overview/?lang=en', 'agency_portal', 'BIS FMCS overview', 'FMCS and CRS boundary', now(), false),
      (version_id, 'https://www.bis.gov.in/fmcs/fmcs-faqs/?lang=en', 'faq', 'BIS FMCS FAQs', 'Voluntary and compulsory certification boundary', now(), false),
      (version_id, 'https://www.bis.gov.in/fmcs/certification-process/how-to-apply/?lang=en', 'agency_portal', 'BIS FMCS application process', 'Application and representative route', now(), false),
      (version_id, 'https://www.bis.gov.in/fmcs/certification-process/who-can-apply/?lang=en', 'agency_portal', 'BIS FMCS who can apply', 'Factory and product applicant conditions', now(), false),
      (version_id, 'https://www.bis.gov.in/hallmarking-jewellers/?lang=en', 'agency_portal', 'BIS hallmarking jewellers', 'Jeweller registration route', now(), false),
      (version_id, 'https://www.bis.gov.in/hallmarking-overview/?lang=en', 'agency_portal', 'BIS hallmarking overview', 'Hallmarking scope and validity', now(), false),
      (version_id, 'https://www.bis.gov.in/wp-content/uploads/2024/01/Revised-Guidelines-for-JEWELLERS-Jan-24.pdf', 'guideline', 'BIS jeweller registration guidelines', 'Jeweller application guidance', now(), false),
      (version_id, 'https://www.bis.gov.in/apply-for-jewellers-registration/?lang=en', 'agency_portal', 'BIS apply for jeweller registration', 'Application route', now(), false),
      (version_id, 'https://www.crsbis.in/BIS/about-crs.do', 'agency_portal', 'BIS CRS portal', 'Electronics and IT registration route', now(), false),
      (version_id, 'https://www.manakonline.in/', 'agency_portal', 'BIS Manakonline portal', 'Official BIS application portal', now(), false),
      (version_id, 'https://www.nsws.gov.in/', 'agency_portal', 'National Single Window System', 'Alternate registration access route', now(), false)
    on conflict do nothing;
    insert into public.opportunity_benefits (opportunity_version_id, benefit_type, label, amount_min, amount_max, percentage, conditions)
    select version_id, item->>'benefit_type', item->>'benefit_label', (item->>'amount_min')::numeric, (item->>'amount_max')::numeric, (item->>'percentage')::numeric, item->'benefit_conditions'
    where not exists (select 1 from public.opportunity_benefits where opportunity_version_id = version_id and label = item->>'benefit_label');
    insert into public.opportunity_requirements (opportunity_version_id, requirement_type, name, description, required)
    select version_id, 'document', item->>'requirement', item->>'requirement_description', true
    where not exists (select 1 from public.opportunity_requirements where opportunity_version_id = version_id and name = item->>'requirement');
    insert into public.eligibility_rule_sets (opportunity_version_id, rules, source_evidence, reviewed)
    select version_id, item->'rules', jsonb_build_array(jsonb_build_object('source_url', item->>'source_url', 'anchor', item->>'source_anchor')), false
    where not exists (select 1 from public.eligibility_rule_sets where opportunity_version_id = version_id);
    insert into public.opportunity_steps (opportunity_version_id, step_number, title, description, official_url)
    select version_id, row_number() over ()::integer, step->>'title', step->>'description', step->>'url'
    from jsonb_array_elements(item->'steps') as steps(step)
    where not exists (select 1 from public.opportunity_steps where opportunity_version_id = version_id);
    insert into public.opportunity_windows (opportunity_version_id, window_type, closes_at, label, source_evidence)
    select version_id, item->>'window_type', (item->>'window_close_at')::timestamptz, item->>'window_label', item->'window_evidence'
    where not exists (select 1 from public.opportunity_windows where opportunity_version_id = version_id);
    insert into public.review_tasks (opportunity_version_id, task_type, status)
    select version_id, 'publish', 'open'
    where not exists (select 1 from public.review_tasks where opportunity_version_id = version_id and task_type = 'publish' and status in ('open', 'in_review'));
  end loop;
end $$;
